639		res, err := r.AnswerSplitIntent(req)
640		assertAnswerSaveFailureEmpty(t, res, err)
641	
642		if err := r.Close(); err != nil {
643			t.Fatal(err)
644		}
645		r2, err := Open(dir)
646		if err != nil {
647			t.Fatalf("失败后原登记册必须仍能正常读取: %v", err)
648		}
649		t.Cleanup(func() { _ = r2.Close() })
650		assertIntentParties(t, r2, "it1", SplitPending, map[string]string{
651			"alice": SplitAnswerAgree, "bob": SplitAnswerAgree, "carol": "",
652		}, false)
653		if _, ok := r2.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
654			t.Fatal("重开后未保存的答复不应占用请求号")
655		}
656		if r2.state.NextIntentSeq != 2 {
657			t.Fatalf("重开后 NextIntentSeq = %d, want 2", r2.state.NextIntentSeq)
658		}
659		if evs, _ := r2.SplitIntentHistory("i1"); len(evs) != 2 {
660			t.Fatalf("重开后历史应仍是 2 条: %+v", evs)
661		}
662	
663		restoreBatchSave(t, r2)
664		res2, err := r2.AnswerSplitIntent(req)
665		if err != nil || res2.Replayed || res2.Status != SplitAgreed {
666			t.Fatalf("重开后重提应正常生效: %+v, err %v", res2, err)
667		}
668		res2, err = r2.AnswerSplitIntent(req)
669		if err != nil || !res2.Replayed || res2.Status != SplitAgreed {
670			t.Fatalf("成功后重提应回放: %+v, err %v", res2, err)
671		}
